work=V/'dash29-patch-build';(work/'a').mkdir(parents=True,exist_ok=True);(work/'b').mkdir(exist_ok=True);attrs=work/'binary.attributes';attrs.write_text('* -text -diff\n');pairs=[(V/'blocker.original.user.js',R/'assets/blocker.home.user.js','policy.user.js'),(V/'ui-v0.1.0/enhance.original.js',R/'assets/enhance.js','enhance.js'),(V/'ui-v0.1.0/main.original.cpp',R/'src/main.cpp','main.cpp'),(V/'ui-v0.1.4/bridge.original.js',R/'assets/bridge.js','bridge.js')];patch=''
